insert into public.academic_concepts(curriculum_id,chapter_title,concept_title,subtopic,position,lesson,lesson_rights_reference,published,topic_id,classification_reference) values(vid,'Motion in a Straight Line','Position and displacement','Introduction',1,'Position locates an object relative to a chosen origin. Displacement compares the finish with the start, without counting the route between them.','Original TIPIX instructional content; pending subject review.',false,tid,'{"verification_status": "pending", "classification": "TIPIX proposed concept", "official_source_url": "https://ncert.nic.in/textbook/pdf/keph102.pdf", "section": "Introduction"}'::jsonb) on conflict do nothing;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,1,'What you will learn','[{"type": "paragraph", "text": "Choose a signed axis; distinguish position, distance and displacement; calculate a change in position."}, {"type": "paragraph", "text": "Position locates an object relative to a chosen origin. Displacement compares the finish with the start, without counting the route between them."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=1) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,2,'Build the idea','[{"type": "paragraph", "text": "Choose a positive direction before calculating. A coordinate is a location, not a distance travelled. Break a journey into legs to find distance; compare only its endpoints to find displacement. On a line, the sign communicates direction."}, {"type": "paragraph", "text": "Distance cannot be negative. Displacement may be positive, negative or zero. A return journey can have a nonzero distance and zero displacement."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=2) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,3,'Formulae, variables and units','[{"type": "formula", "text": "Δx = x_final − x_initial; distance = sum of the absolute lengths of each leg."}, {"type": "paragraph", "text": "Position x and displacement Δx: metres (m). State the positive direction alongside a signed answer."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=3) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,4,'Explore motion','[{"type": "motion", "text": "Change the starting velocity, acceleration and time. Compare signed displacement and velocity."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=4) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,5,'Worked example and everyday connection','[{"type": "paragraph", "text": "A delivery robot starts at x = −3 m, visits x = 9 m and stops at x = 4 m. Displacement = 4 − (−3) = +7 m. Distance = |9 − (−3)| + |4 − 9| = 12 + 5 = 17 m."}, {"type": "paragraph", "text": "A batter who runs to the other crease and back covers ground but finishes at the starting position: the net displacement is zero."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=5) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,6,'Common mistakes and exam checks','[{"type": "paragraph", "text": "Adding every leg gives distance, not displacement. A negative starting coordinate must be subtracted with brackets. Negative displacement does not mean negative distance."}, {"type": "paragraph", "text": "Write the endpoints first. Check that |displacement| ≤ distance. Equality requires no reversal along the line."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=6) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,7,'Summary and mini check','[{"type": "paragraph", "text": "Choose origin and direction → record endpoints → subtract final minus initial → give metres and direction."}]'::jsonb,'A robot returns to its starting coordinate. Which quantity must be zero?','["Distance travelled", "Displacement", "Time taken"]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=7) returning id into taskid;
