insert into public.academic_topics(chapter_id,title,position) values(hid,'Instantaneous velocity and speed',2) on conflict do nothing;
insert into public.academic_concepts(curriculum_id,chapter_title,concept_title,subtopic,position,lesson,lesson_rights_reference,published,topic_id,classification_reference) values(vid,'Motion in a Straight Line','Instantaneous velocity and speed','Instantaneous velocity and speed',2,'Velocity describes how position is changing at a particular moment. Speed describes the magnitude of that change without its direction.','Original TIPIX instructional content; pending subject review.',false,tid,'{"verification_status": "pending", "classification": "TIPIX proposed concept", "official_source_url": "https://ncert.nic.in/textbook/pdf/keph102.pdf", "section": "Instantaneous velocity and speed"}'::jsonb) on conflict do nothing;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,1,'What you will learn','[{"type": "paragraph", "text": "Relate velocity to the slope of a position–time graph; calculate instantaneous velocity; distinguish speed from signed velocity."}, {"type": "paragraph", "text": "Velocity describes how position is changing at a particular moment. Speed describes the magnitude of that change without its direction."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=1) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,2,'Build the idea','[{"type": "paragraph", "text": "Average velocity compares two times. Instantaneous velocity examines a shrinking interval around one time. On a smooth position–time graph it is the tangent slope. If a formula x(t) is supplied, differentiate it with respect to time."}, {"type": "paragraph", "text": "A horizontal tangent means zero instantaneous velocity. A negative slope means motion towards decreasing x. Equal speed does not imply equal velocity."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=2) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,3,'Formulae, variables and units','[{"type": "formula", "text": "v_average = Δx/Δt; v(t) = dx/dt; instantaneous speed = |v(t)|."}, {"type": "paragraph", "text": "Time t: seconds (s); position x: metres (m); velocity and speed: metres per second (m/s)."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=3) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,4,'Explore motion','[{"type": "motion", "text": "Change the starting velocity, acceleration and time. Compare signed displacement and velocity."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=4) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,5,'Worked example and everyday connection','[{"type": "paragraph", "text": "For x(t) = 2t² − 6t + 1 metres, v(t) = 4t − 6 m/s. At t = 1 s, v = −2 m/s and speed = 2 m/s. At t = 1.5 s the tangent is horizontal."}, {"type": "paragraph", "text": "A game character can run left at 5 m/s or right at 5 m/s. The speed is unchanged but the signed velocity reverses."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=5) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,6,'Common mistakes and exam checks','[{"type": "paragraph", "text": "Do not use x/t as instantaneous velocity. Do not report a negative speed. Average speed uses total distance, not net displacement."}, {"type": "paragraph", "text": "Differentiate first, then substitute the requested time. Inspect units of every coefficient."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=6) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,7,'Summary and mini check','[{"type": "paragraph", "text": "Position–time tangent slope gives velocity; take its absolute value to obtain speed."}]'::jsonb,'The position–time tangent slope is −3 m/s. What is the speed?','["−3 m/s", "0 m/s", "3 m/s"]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=7) returning id into taskid;
