insert into public.academic_topics(chapter_id,title,position) values(hid,'Acceleration',3) on conflict do nothing;
insert into public.academic_concepts(curriculum_id,chapter_title,concept_title,subtopic,position,lesson,lesson_rights_reference,published,topic_id,classification_reference) values(vid,'Motion in a Straight Line','Acceleration','Acceleration',3,'Acceleration measures how quickly velocity changes. It can change the speed, the direction, or both.','Original TIPIX instructional content; pending subject review.',false,tid,'{"verification_status": "pending", "classification": "TIPIX proposed concept", "official_source_url": "https://ncert.nic.in/textbook/pdf/keph102.pdf", "section": "Acceleration"}'::jsonb) on conflict do nothing;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,1,'What you will learn','[{"type": "paragraph", "text": "Calculate average and instantaneous acceleration; distinguish negative acceleration from slowing down."}, {"type": "paragraph", "text": "Acceleration measures how quickly velocity changes. It can change the speed, the direction, or both."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=1) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,2,'Build the idea','[{"type": "paragraph", "text": "On a line, compare signed velocities. Acceleration with the same sign as velocity increases speed; opposite signs decrease speed until any reversal. A velocity–time graph has acceleration as its slope."}, {"type": "paragraph", "text": "An object can have zero velocity at one instant and nonzero acceleration. Constant velocity implies zero acceleration; constant acceleration allows velocity to change uniformly."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=2) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,3,'Formulae, variables and units','[{"type": "formula", "text": "a_average = (v_final − v_initial)/Δt; a(t) = dv/dt = d²x/dt²."}, {"type": "paragraph", "text": "Acceleration: metres per second squared (m/s²). A value +2 m/s² means velocity increases by 2 m/s each second."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=3) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,4,'Explore motion','[{"type": "motion", "text": "Change the starting velocity, acceleration and time. Compare signed displacement and velocity."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=4) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,5,'Worked example and everyday connection','[{"type": "paragraph", "text": "A cart changes velocity from −8 to −2 m/s in 3 s. Average acceleration = [−2 − (−8)]/3 = +2 m/s². It is slowing down because its speed falls from 8 to 2 m/s."}, {"type": "paragraph", "text": "A lift accelerating upwards while descending can reduce its downward speed. The direction of motion and acceleration need not match."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=5) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,6,'Common mistakes and exam checks','[{"type": "paragraph", "text": "Negative acceleration does not always mean slowing down. Use signed velocities and the time interval, not the clock reading."}, {"type": "paragraph", "text": "For a speed-change question, compare the signs of v and a. At a turning instant, examine times just before and after it."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=6) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,7,'Summary and mini check','[{"type": "paragraph", "text": "Velocity change divided by elapsed time gives average acceleration. Graph slope or differentiation gives instantaneous acceleration."}]'::jsonb,'Velocity is negative and acceleration is positive, before any reversal. What happens to speed?','["It decreases", "It increases", "It must remain constant"]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=7) returning id into taskid;
