insert into public.academic_topics(chapter_id,title,position) values(hid,'Kinematic equations for uniformly accelerated motion',4) on conflict do nothing;
insert into public.academic_concepts(curriculum_id,chapter_title,concept_title,subtopic,position,lesson,lesson_rights_reference,published,topic_id,classification_reference) values(vid,'Motion in a Straight Line','Constant-acceleration equations','Kinematic equations for uniformly accelerated motion',4,'When acceleration stays constant, a small set of equations connects the starting velocity, finishing velocity, displacement and elapsed time.','Original TIPIX instructional content; pending subject review.',false,tid,'{"verification_status": "pending", "classification": "TIPIX proposed concept", "official_source_url": "https://ncert.nic.in/textbook/pdf/keph102.pdf", "section": "Kinematic equations for uniformly accelerated motion"}'::jsonb) on conflict do nothing;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,1,'What you will learn','[{"type": "paragraph", "text": "Choose an equation from known quantities; use signed displacement; check the constant-acceleration assumption."}, {"type": "paragraph", "text": "When acceleration stays constant, a small set of equations connects the starting velocity, finishing velocity, displacement and elapsed time."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=1) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,2,'Build the idea','[{"type": "paragraph", "text": "Let the initial instant be t = 0. Use one consistent positive direction. The area beneath the straight velocity–time line gives signed displacement. These equations cannot be applied as one interval when acceleration changes partway through."}, {"type": "paragraph", "text": "The symbol s is displacement, not always total distance. Free-fall problems use a signed gravitational acceleration. More than one time can correspond to the same position."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=2) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,3,'Formulae, variables and units','[{"type": "formula", "text": "v = u + at; s = ut + ½at²; v² = u² + 2as; s = ½(u + v)t. All require constant a."}, {"type": "paragraph", "text": "u, v: m/s; a: m/s²; s: m; t: s. Convert km/h to m/s before substitution."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=3) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,4,'Explore motion','[{"type": "motion", "text": "Change the starting velocity, acceleration and time. Compare signed displacement and velocity."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=4) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,5,'Worked example and everyday connection','[{"type": "paragraph", "text": "A cart starts at 2 m/s and accelerates at 3 m/s² for 4 s. Final velocity = 2 + 3×4 = 14 m/s. Displacement = 2×4 + ½×3×4² = 32 m. The average velocity 8 m/s also gives 32 m in 4 s."}, {"type": "paragraph", "text": "A straight velocity–time segment in a train simulation can be modelled with constant acceleration; a curved segment requires a different approach."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=5) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,6,'Common mistakes and exam checks','[{"type": "paragraph", "text": "Do not forget the square on time or the factor one-half. Do not use constant-acceleration equations for a variable acceleration. A squared velocity equation cannot by itself determine direction."}, {"type": "paragraph", "text": "List u, v, a, s and t. Select an equation without the unwanted unknown. Verify physical time is nonnegative."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=6) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,7,'Summary and mini check','[{"type": "paragraph", "text": "Check constant acceleration → choose a positive axis → select an equation → substitute SI units → check the result."}]'::jsonb,'Which condition is required for s = ut + ½at² with a single value of a?','["Zero initial velocity", "Constant acceleration throughout the interval", "Positive velocity throughout"]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=7) returning id into taskid;
