insert into public.academic_concepts(curriculum_id,chapter_title,concept_title,subtopic,position,lesson,lesson_rights_reference,published,topic_id,classification_reference) values(vid,'Motion in a Straight Line','Relative velocity on a line','Relative velocity',5,'Relative velocity answers how fast the separation changes when one moving object is used as the reference.','Original TIPIX instructional content; pending subject review.',false,tid,'{"verification_status": "pending", "classification": "TIPIX proposed concept", "official_source_url": "https://ncert.nic.in/textbook/pdf/keph102.pdf", "section": "Relative velocity"}'::jsonb) on conflict do nothing;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,1,'What you will learn','[{"type": "paragraph", "text": "Express one object’s velocity as observed from another; calculate closing and separation rates."}, {"type": "paragraph", "text": "Relative velocity answers how fast the separation changes when one moving object is used as the reference."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=1) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,2,'Build the idea','[{"type": "paragraph", "text": "First express both velocities on the same axis relative to the ground. Subtract the observer’s velocity from the object’s velocity. Do not blindly add speeds: the algebra already handles opposite directions."}, {"type": "paragraph", "text": "Equal velocities produce zero relative velocity. Reversing observer and object changes the sign. A negative relative velocity means motion in the observer’s negative direction."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=2) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,3,'Formulae, variables and units','[{"type": "formula", "text": "v_A/B = v_A − v_B; for constant velocities, relative displacement = initial separation + v_A/B × t."}, {"type": "paragraph", "text": "All velocities must use the same unit, normally m/s. Separations use metres and encounter times use seconds."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=3) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,4,'Explore motion','[{"type": "motion", "text": "Change the starting velocity, acceleration and time. Compare signed displacement and velocity."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=4) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,5,'Worked example and everyday connection','[{"type": "paragraph", "text": "A bus moves east at 16 m/s and a cyclist east at 6 m/s. The cyclist sees the bus move east at 16 − 6 = 10 m/s. If they move towards one another at these speeds, the closing speed is 22 m/s."}, {"type": "paragraph", "text": "In a racing game, two cars moving at equal velocity keep the same gap even though both move rapidly relative to the track."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=5) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,6,'Common mistakes and exam checks','[{"type": "paragraph", "text": "Do not confuse v_A/B with v_B/A. Do not add speeds for objects moving in the same direction. State which object is the observer."}, {"type": "paragraph", "text": "Draw one axis, attach signs to both ground velocities, then subtract. Check whether the calculated separation grows or shrinks."}]'::jsonb,null,'[]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=6) returning id into taskid;
insert into public.academic_learning_tasks(concept_id,position,title,blocks,check_prompt,check_options) select cid,7,'Summary and mini check','[{"type": "paragraph", "text": "Choose observer B → express both signed ground velocities → compute v_A − v_B → interpret the sign."}]'::jsonb,'Two cars move east with equal velocities. What is one car’s velocity relative to the other?','["Twice the ground velocity", "Zero", "The negative ground velocity"]'::jsonb where not exists(select 1 from public.academic_learning_tasks where concept_id=cid and position=7) returning id into taskid;
