alter table public.academic_verified_question_bank add column if not exists hint text;
alter table public.academic_concepts add column if not exists classification_reference jsonb not null default '{}'::jsonb;
create table if not exists public.academic_books(id uuid primary key default gen_random_uuid(),curriculum_id uuid not null references public.academic_curriculum_versions,title text not null,part text not null,language text not null default 'English',official_source_url text not null,last_verified_at timestamptz,unique(curriculum_id,title,part));
alter table public.academic_books enable row level security;
revoke all on public.academic_books from public,anon,authenticated;
alter table public.academic_chapters add column if not exists book_id uuid references public.academic_books;
create index if not exists academic_chapter_book on public.academic_chapters(book_id);
do $import$ declare vid uuid;bid uuid;hid uuid;tid uuid;cid uuid;sid uuid;qid uuid;taskid uuid;begin
select id into strict vid from public.academic_curriculum_versions where board='NCERT' and academic_year='2026-27' and class_level=11 and subject='Physics';
select id into strict bid from public.academic_books where curriculum_id=vid and title='Physics Part I' and part='I';
select id into strict hid from public.academic_chapters where curriculum_id=vid and title='Motion in a Straight Line';
select id into strict sid from public.academic_source_registry where source_code='tipix-original';
select id into strict tid from public.academic_topics where chapter_id=hid and title='Introduction';
select id into strict cid from public.academic_concepts where curriculum_id=vid and chapter_title='Motion in a Straight Line' and concept_title='Position and displacement';
if taskid is not null then insert into tipix_private.academic_task_keys(task_id,answer,explanation) values(taskid,1,'Its final and initial coordinates match, so their difference is zero. It may still have travelled.');end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'11'::jsonb,'7 − (−4) = +11 m. Subtract the starting coordinate, including its sign.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'8'::jsonb,'The signed changes add: +14 − 6 = +8 m. The 20 m path length is not displacement.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'-13'::jsonb,'Final minus initial is −5 − 8 = −13 m, towards the negative direction.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'23'::jsonb,'The two leg lengths are |12 − 2| = 10 m and |−1 − 12| = 13 m. Distance is 23 m.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'0'::jsonb,'The endpoints are equal. Net displacement is −6 − (−6) = 0 m, although distance is 30 m.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'14'::jsonb,'Let E and W be eastward and westward distances. E + W = 38 and E − W = 10. Subtracting gives 2W = 28, so W = 14 m.',0);end if;
select id into strict tid from public.academic_topics where chapter_id=hid and title='Instantaneous velocity and speed';
select id into strict cid from public.academic_concepts where curriculum_id=vid and chapter_title='Motion in a Straight Line' and concept_title='Instantaneous velocity and speed';
if taskid is not null then insert into tipix_private.academic_task_keys(task_id,answer,explanation) values(taskid,2,'Speed is the magnitude of velocity, so |−3| = 3 m/s.');end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'9'::jsonb,'Speed is |velocity| = |−9| = 9 m/s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'5'::jsonb,'Differentiating x with respect to t gives the constant velocity 5 m/s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'10'::jsonb,'v(t) = 6t − 2. At 2 s this is 12 − 2 = 10 m/s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'-3'::jsonb,'v(t) = 3t² − 6. At t = 1 s it equals −3 m/s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'2'::jsonb,'v = 4t − 8. Solving 4t − 8 = 0 gives t = 2 s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'3'::jsonb,'v = 3t² − 6t = −3 m/s at t = 1 s. Speed is the magnitude, 3 m/s.',0);end if;
select id into strict tid from public.academic_topics where chapter_id=hid and title='Acceleration';
select id into strict cid from public.academic_concepts where curriculum_id=vid and chapter_title='Motion in a Straight Line' and concept_title='Acceleration';
if taskid is not null then insert into tipix_private.academic_task_keys(task_id,answer,explanation) values(taskid,0,'Acceleration opposes the current velocity, so the magnitude of velocity decreases.');end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'3'::jsonb,'(15 − 3)/4 = 3 m/s².',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'0'::jsonb,'There is no change in velocity, so acceleration is zero.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'3'::jsonb,'[−4 − (−10)]/2 = +3 m/s². The vehicle is slowing while moving in the negative direction.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'16'::jsonb,'a(t) = dv/dt = 8t. At 2 s, a = 16 m/s².',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'-2'::jsonb,'The signed velocity change is −2 − 6 = −8 m/s. Dividing by 4 s gives −2 m/s².',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'26'::jsonb,'Differentiate twice: v = 6t² − 10t + 4; a = 12t − 10. At t = 3 s, a = 26 m/s².',0);end if;
select id into strict tid from public.academic_topics where chapter_id=hid and title='Kinematic equations for uniformly accelerated motion';
select id into strict cid from public.academic_concepts where curriculum_id=vid and chapter_title='Motion in a Straight Line' and concept_title='Constant-acceleration equations';
if taskid is not null then insert into tipix_private.academic_task_keys(task_id,answer,explanation) values(taskid,1,'The equation assumes a constant acceleration; u can be nonzero and velocity can change sign.');end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'10'::jsonb,'v = u + at = 0 + 2×5 = 10 m/s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'2'::jsonb,'a = (v − u)/t = (10 − 4)/3 = 2 m/s².',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'28'::jsonb,'s = ut + ½at² = 3×4 + ½×2×16 = 28 m.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'24'::jsonb,'At rest v = 0. From v² = u² + 2as: 0 = 144 − 6s, so s = 24 m.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'2'::jsonb,'Up is positive, so a = −10 m/s² and v = 0 at the top. 0 = 20 − 10t gives t = 2 s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'13'::jsonb,'It stops after 3 s, having travelled 6×3 − 3² = 9 m. During the remaining 2 s it travels ½×2×2² = 4 m backwards. Total distance is 13 m, although displacement is 5 m.',0);end if;
select id into strict tid from public.academic_topics where chapter_id=hid and title='Relative velocity';
select id into strict cid from public.academic_concepts where curriculum_id=vid and chapter_title='Motion in a Straight Line' and concept_title='Relative velocity on a line';
if taskid is not null then insert into tipix_private.academic_task_keys(task_id,answer,explanation) values(taskid,1,'Subtracting equal velocities gives zero, so their separation stays constant.');end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'8'::jsonb,'v_A/B = 13 − 5 = +8 m/s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'0'::jsonb,'Their equal ground velocities subtract to zero.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'12'::jsonb,'v_A = +8 and v_B = −4. Thus v_A/B = 8 − (−4) = +12 m/s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'-11'::jsonb,'v_cyclist/bus = 4 − 15 = −11 m/s, backwards relative to the bus.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'9'::jsonb,'The closing speed is 7 + 3 = 10 m/s. Time = 90/10 = 9 s.',0);end if;
if qid is not null then insert into tipix_private.academic_answer_keys(question_id,answer,explanation,tolerance) values(qid,'15'::jsonb,'The gap shrinks at 22 − 14 = 8 m/s. Time = 120/8 = 15 s. Using the sum would incorrectly assume opposite directions.',0);end if;
end $import$;
